/*
 * A032626  Primes that are concatenations of n with n + 3.
 * https://oeis.org/A032626
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the nth prime obtained by concatenating an integer k
 *            with k+3. The sequence is generated by testing k = 1, 2, … until
 *            n such numbers are found and the corresponding prime
 *            concatenations are stored
 * Range:     u8 n <= 1, u16 n <= 12, u32 n <= 12, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   concat_parts, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"   /* bool is_prime_big(seq_t n);     */
#include "../utils/concat_parts.h"   /* seq_t concat_parts(idx_t a,b); */

seq_t a(idx_t n)
{
    /* Static state to avoid recomputation on subsequent calls */
    static idx_t last_k     = 0;   /* largest k tested so far          */
    static seq_t *cache     = NULL;/* cache of found prime concatenations */
    static size_t cache_sz  = 0;    /* number of cached values            */
    static size_t cache_cap = 0;    /* allocated capacity of cache        */

    /* Grow the sequence until we have at least n terms */
    while (cache_sz < n)
    {
        /* Next candidate k */
        ++last_k;

        /* Form candidate number concat(k, k+3) */
        seq_t candidate = concat_parts(last_k, last_k + 3);

        /* If it is prime, store it */
        if (is_prime_big(candidate))
        {
            /* Grow cache if necessary */
            if (cache_sz == cache_cap)
            {
                size_t new_cap = cache_cap ? cache_cap * 2 : 8;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_sz++] = candidate;
        }
    }

    /* Return the requested term (1‑based indexing) */
    return cache[n - 1];
}
